    [('LocalProxy', 'request、current_app、g、session 的类型'), (f'{c[0] / c[1]:.1f}×', '通过代理访问属性相对直接访问的耗时倍数'), ('4 / 4', '4 个线程各自读到不同的 request.path')],
    [('代理对象', '<p>上一篇:<a href="flask-request-context.html">Flask Request Context</a>;下一篇:<a href="flask-context-local-isolation.html">Context Local 与线程隔离</a>。</p>'), ('LocalProxy 与 ContextVar', None), ('线程隔离', None), ('访问开销', None), ('g 对象', None), ('传给线程', None)],
